const buses = [
  {
    id: 1,
    name: "Standard",
    extraPrice: 0,
    seats: 45,
  },
  {
    id: 2,
    name: "VIP Coach",
    extraPrice: 1500,
    seats: 32,
  },
  {
    id: 3,
    name: "Shuttle",
    extraPrice: -500,
    seats: 18,
  },
];

export default buses;
